  if(data.Population?.Pilots.Any(p=>p.WingP<1||p.WingP>5||p.SquadP<1||p.SquadP>5||!DoctrinesP.Contains(p.DoctrineP)||p.RankP is not("Member" or "Squad commander" or "Wing commander" or "Fleet commander")||!float.IsFinite(p.PendingAmountP+p.PendingRangeP)||p.PendingAmountP<0||p.PendingRangeP<0||p.RetainedFitsP==null)==true)throw new InvalidDataException("Invalid fleet hierarchy or cycle.");
 }
